fn DeathMatchBattle::new(version: usize, goal: BattlePlanGoal, data: &OperationData, player: &PlayerState) -> DeathMatchBattle

// L747
let mut chats: Vec<Chat> = Vec::new();          // RawVec{cap=0, ptr=dangling(8)}, len=0

// L749  — 유일한 분기
if goal.tag == 0 {                               // BattlePlanGoal::TryKill(target, _)
    let target = *(goal + 0x8);                  // TryKill.__0 : usize
    chats.grow_one();                            // cap 0 -> 1 (push 의 slow path, 인라인됨)
    let p = chats.raw.ptr;
    p[0x0] = 3u8;                                // Chat::Battle
    p[0x8] = target;                             // Chat::Battle.__0
    p[0x10] = 0;                                 // Chat::Battle.__1
    chats.len = 1;
}
// tag 1(Support) / 2(Response) / 3(Avoid) 는 아무것도 안 함 -> chats 는 빈 채로 남는다

// L753
let sub_goal: BattleSubPlanGoal = BattlePlanGoal::base_sub_goal(&goal, version, player, data);
//   -> { i64, i64 } 로 반환, out+0xe8 / out+0xf0 에 각각 저장

// L754
let g = *(data.cache);                           // &dyn AbstractGame (팻포인터)
let start_tick: usize = (g.vtable[0x28])(g.data);  // 슬롯 5, 인자는 self 뿐, i64 반환

// L753~755  — 구조체 리터럴 (Self { .. }) 을 sret 버퍼에 직접 기록
Self {
    // --- 전부 None ---
    support_target:   None,   // 0x000  Option<usize>           i64 태그 0
    region:           None,   // 0x010  Option<BattleRegion>    i64 태그 0
    well_runaway:     None,   // 0x030  Option<usize>
    death_focus:      None,   // 0x040  Option<usize>
    seal_basis:       None,   // 0x050  Option<(usize,usize,usize)>
    hold_scene_basis: None,   // 0x070  Option<(usize,usize,usize)>
    repo_scene_basis: None,   // 0x090  Option<(usize,usize)>
    flee_dir:         None,   // 0x0a8  Option<(i64,i64)>
    far_noout_since:  None,   // 0x0c0  Option<usize>
    dive_tower:       None,   // 0x17a  Option<TowerType>          니치 태그 255
    main_objective:   None,   // 0x17b  Option<Option<MainObjective>> 니치 태그 255

    // --- 인자/호출 결과에서 옴 ---
    main_goal:  goal,         // 0x0d0  memcpy 24B (인자 goal 원본 보존)
    sub_goal:   sub_goal,     // 0x0e8  base_sub_goal 결과
    chats:      chats,        // 0x0f8  memcpy 24B (위에서 만든 Vec 이동)
    start_tick: start_tick,   // 0x110  플랜 생성 시각 = 이후 모든 경과시간의 기준점

    // --- 센티널/0 ---
    flee_die: i64::MAX,       // 0x118  '미발생' 센티널
    // 0x120..0x170 = memset(0, 80B):
    trade_lean: 0,            // 0x120  i64
    lean_last_tick: 0,        // 0x128
    scene_change_tick: 0,     // 0x130
    last_act_tick: 0,         // 0x138
    idle_spec_tick: 0,        // 0x140
    last_swing_tick: 0,       // 0x148
    ep_follow_until: 0,       // 0x150
    idle_prev_pos: (0, 0),    // 0x158  tuple<u64,u64>
    last_unseal_tick: 0,      // 0x168

    // --- bool 전부 false ---
    with_dive: false,         // 0x170
    help_called: false,       // 0x171
    dive_abandoned: false,    // 0x172
    dodge_commit: false,      // 0x173
    last_stand: false,        // 0x174
    had_ult_ready: false,     // 0x175

    // --- 열거형 초기 상태 ---
    stance:          DeathStance::Commit,   // 0x176  태그 0 (다른 값: 1=Reposition 2=HoldForSpawn)
    tactic:          BattleTactic::Standard,// 0x177  태그 0 (1=Frontline 2=BacklineDPS 3=SkillBurst 4=Peel 5=AllIn 6=Disengage)
    scene:           DmScene::Stand,        // 0x178  태그 0 (1=Engage 2=Withdraw 3=Hold 4=Reposition 5=LastStand 6=Fallback)
    scene_last_from: DmScene::Stand,        // 0x179  태그 0
    lean_last_sign:  0,                     // 0x17e  i8
}

// 언와인드 경로(%16): grow_one / base_sub_goal / vtable 호출 중 패닉하면
//   cleanuppad 에서 chats(Vec<Chat>) 의 drop_glue 만 호출하고 재전파.

★판단에 직결되는 초기값 정리
 - start_tick 만이 '외부에서 읽어오는' 값이다(현재 틱). 나머지는 전부 상수.
 - flee_die = i64::MAX 라서 'flee_die 이후인가' 류 비교는 초기에 항상 거짓이 된다.
 - scene/scene_last_from 이 둘 다 Stand 이고 scene_change_tick=0 이라
   '씬이 바뀐 지 N틱' 계산은 생성 직후 start_tick 만큼 큰 값이 된다(0 기준).
 - chats 는 TryKill 일 때만 원소 1개(Battle(target,0)), 그 외 목표에선 빈 Vec.
